# ---------------------------------------------------------------------------
# is_generated_file — filename patterns
# ---------------------------------------------------------------------------

class TestIsGeneratedFileByName:
    def test_lockfiles(self):
        assert is_generated_file("package-lock.json")
        assert is_generated_file("yarn.lock")
        assert is_generated_file("poetry.lock")
        assert is_generated_file("Cargo.lock")  # case-insensitive
        assert is_generated_file("go.sum")

    def test_minified(self):
        assert is_generated_file("app.min.js")
        assert is_generated_file("styles.min.css")
        assert is_generated_file("vendor.bundle.js")

    def test_protobuf(self):
        assert is_generated_file("api.pb.go")
        assert is_generated_file("service.pb.py")
        assert is_generated_file("types.pb.cc")

    def test_snapshots(self):
        assert is_generated_file("Component.test.tsx.snap")
        assert is_generated_file("__snapshots__/foo.snap")

    def test_vendor_dirs(self):
        assert is_generated_file("vendor/github.com/pkg/errors/errors.go")
        assert is_generated_file("node_modules/lodash/index.js")
        assert is_generated_file("dist/bundle.js")

    def test_migrations(self):
        assert is_generated_file("migrations/0001_initial.py")
        assert is_generated_file("db/migrations/20230101_create_users.sql")

    def test_generated_dirs(self):
        assert is_generated_file("__generated__/schema.ts")
        assert is_generated_file("src/generated/types.go")

    def test_normal_source_not_generated(self):
        assert not is_generated_file("src/main.py")
        assert not is_generated_file("lib/utils.ts")
        assert not is_generated_file("package.json")  # not lock
        assert not is_generated_file("README.md")
        assert not is_generated_file("tests/test_foo.py")

    def test_svg_detected(self):
        assert is_generated_file("logo.svg")
        assert is_generated_file("icons/arrow.svg")

    def test_empty_filename(self):
        assert not is_generated_file("")
        assert not is_generated_file(None)  # type: ignore


# ---------------------------------------------------------------------------
# is_generated_file — patch content analysis
# ---------------------------------------------------------------------------

class TestIsGeneratedFileByPatch:
    def test_generated_marker_in_header(self):
        patch = (
            "@@ -0,0 +1,5 @@\n"
            "+// Code generated by protoc-gen-go. DO NOT EDIT.\n"
            "+package api\n"
            "+\n"
            "+type Foo struct{}\n"
        )
        assert is_generated_file("api/types.go", patch)

    def test_auto_generated_marker(self):
        patch = (
            "@@ -0,0 +1,3 @@\n"
            "+# This file is auto-generated\n"
            "+CONFIG = {}\n"
        )
        assert is_generated_file("config.py", patch)

    def test_at_generated_marker(self):
        patch = (
            "@@ -0,0 +1,3 @@\n"
            "+/* @generated */\n"
            "+export const x = 1;\n"
        )
        assert is_generated_file("output.js", patch)

    def test_normal_patch_not_generated(self):
        patch = (
            "@@ -1,3 +1,5 @@\n"
            " def hello():\n"
            "-    print('hello')\n"
            "+    print('hello world')\n"
            "+    return True\n"
        )
        assert not is_generated_file("src/hello.py", patch)

    def test_minified_content_high_entropy(self):
        # Simulate minified JS: long line, high entropy, hard to compress
        import random
        random.seed(42)
        chars = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789(){}[];:,.'\"!@#$%^&*"
        minified = "".join(random.choice(chars) for _ in range(2000))
        patch = "@@ -0,0 +1,1 @@\n+" + minified
        assert is_generated_file("app.js", patch)

    def test_repetitive_generated_code(self):
        # Extremely repetitive machine-generated code (very low compression ratio)
        line = "+    this.field_{i} = value_{i};\n"
        lines = [f"+    this.field_{i} = value_{i};" for i in range(200)]
        patch = "@@ -0,0 +1,200 @@\n" + "\n".join(lines)
        # This should have extremely low compression ratio
        result = is_generated_file("generated_model.java", patch)
        # May or may not trigger depending on exact entropy/ratio — just ensure no crash
        assert isinstance(result, bool)


# ---------------------------------------------------------------------------
# Shannon entropy helper
# ---------------------------------------------------------------------------

class TestShannonEntropy:
    def test_empty(self):
        assert _shannon_entropy(b"") == 0.0

    def test_single_byte(self):
        assert _shannon_entropy(b"aaaa") == 0.0  # no variance

    def test_uniform_distribution(self):
        # 256 distinct bytes: max entropy = 8 bits
        data = bytes(range(256))
        entropy = _shannon_entropy(data)
        assert abs(entropy - 8.0) < 0.01

    def test_low_entropy_text(self):
        data = b"aaabbbccc"
        entropy = _shannon_entropy(data)
        assert entropy < 2.0  # very low

    def test_code_like_entropy(self):
        data = b"def hello():\n    print('hello world')\n    return True\n"
        entropy = _shannon_entropy(data)
        assert 3.0 < entropy < 5.5  # normal code range


# ---------------------------------------------------------------------------
# Compression ratio helper
# ---------------------------------------------------------------------------

class TestCompressionRatio:
    def test_empty(self):
        assert _compression_ratio(b"") == 1.0

    def test_repetitive_compresses_well(self):
        data = b"x" * 10000
        ratio = _compression_ratio(data)
        assert ratio < 0.05  # should compress very well

    def test_random_compresses_poorly(self):
        import os
        data = os.urandom(1000)
        ratio = _compression_ratio(data)
        assert ratio > 0.8  # random data doesn't compress well


