class TestGetPrEffectiveChanges:
    def test_no_files_falls_back_to_pr_counts(self):
        user = make_user(id=1, login="alice")
        repo = make_repo(id=1, name="repo", owner=user)
        pr = make_pr(1, user, repo, additions=100, deletions=50)
        bundle = make_bundle(users=[user], repositories=[repo], pull_requests=[pr])
        ctx = make_context(bundle, user_login="alice")
        eff_add, eff_del, gen = get_pr_effective_changes(ctx.ledger, pr)
        assert eff_add == 100
        assert eff_del == 50
        assert gen == 0

    def test_excludes_generated_files(self):
        user = make_user(id=1, login="alice")
        repo = make_repo(id=1, name="repo", owner=user)
        pr = make_pr(1, user, repo, additions=200, deletions=100)
        files = [
            make_file("a1", "src/main.py", additions=80, deletions=30, changes=110, pr_number=1),
            make_file("a2", "package-lock.json", additions=120, deletions=70, changes=190, pr_number=1),
        ]
        bundle = make_bundle(users=[user], repositories=[repo], pull_requests=[pr], files=files)
        ctx = make_context(bundle, user_login="alice")
        eff_add, eff_del, gen = get_pr_effective_changes(ctx.ledger, pr)
        assert eff_add == 80
        assert eff_del == 30
        assert gen == 190  # 120 + 70

    def test_all_generated(self):
        user = make_user(id=1, login="alice")
        repo = make_repo(id=1, name="repo", owner=user)
        pr = make_pr(1, user, repo, additions=100, deletions=50)
        files = [
            make_file("a1", "yarn.lock", additions=100, deletions=50, changes=150, pr_number=1),
        ]
        bundle = make_bundle(users=[user], repositories=[repo], pull_requests=[pr], files=files)
        ctx = make_context(bundle, user_login="alice")
        eff_add, eff_del, gen = get_pr_effective_changes(ctx.ledger, pr)
        assert eff_add == 0
        assert eff_del == 0
        assert gen == 150


