# PR size distribution — generated-file filtering integration
# ---------------------------------------------------------------------------

class TestPRSizeDistributionGeneratedFilter:
    def test_lockfile_excluded_changes_size_category(self):
        """A PR that is 'medium' by raw lines becomes 'trivial' after excluding lockfile."""
        user = make_user(id=1, login="alice")
        repo = make_repo(id=1, name="repo", owner=user)
        # PR with 5 real lines + 500 lockfile lines
        pr = make_pr(1, user, repo, additions=505, deletions=0)
        files = [
            make_file("a1", "src/config.py", additions=5, deletions=0, changes=5, pr_number=1),
            make_file("a2", "poetry.lock", additions=500, deletions=0, changes=500, pr_number=1),
        ]
        bundle = make_bundle(users=[user], repositories=[repo], pull_requests=[pr], files=files)
        ctx = make_context(bundle, user_login="alice")

        metric = PRSizeDistribution()
        res = metric.run(ctx)
        # Effective: 5 additions + 0 deletions * 0.5 = 5 weighted → trivial
        assert 1 in res.details["trivial_pr_numbers"]
        assert res.details["generated_lines_excluded"] == 500

    def test_no_generated_files_unchanged(self):
        """PR with no generated files: raw and effective are the same."""
        user = make_user(id=1, login="alice")
        repo = make_repo(id=1, name="repo", owner=user)
        pr = make_pr(1, user, repo, additions=100, deletions=50)
        files = [
            make_file("a1", "src/main.py", additions=100, deletions=50, changes=150, pr_number=1),
        ]
        bundle = make_bundle(users=[user], repositories=[repo], pull_requests=[pr], files=files)
        ctx = make_context(bundle, user_login="alice")

        metric = PRSizeDistribution()
        res = metric.run(ctx)
        assert res.details["generated_lines_excluded"] == 0
        assert res.details["medium_pr_count"] == 1  # 100 + 50*0.5 = 125 → medium


