class TestTrivialContributionRateGeneratedFilter:
    def test_lockfile_pr_becomes_trivial(self):
        """A PR that looks non-trivial by raw lines becomes trivial after excluding generated."""
        user = make_user(id=1, login="alice")
        repo = make_repo(id=1, name="repo", owner=user)
        start = DEFAULT_START
        pr = make_pr(1, user, repo, additions=505, deletions=0, base_time=start)
        files = [
            make_file("a1", "src/fix.py", additions=5, deletions=0, changes=5, pr_number=1),
            make_file("a2", "package-lock.json", additions=500, deletions=0, changes=500, pr_number=1),
        ]
        bundle = make_bundle(users=[user], repositories=[repo], pull_requests=[pr], files=files)
        ctx = make_context(bundle, user_login="alice", start_date=start, end_date=start + timedelta(days=30))

        metric = TrivialContributionRate()
        res = metric.run(ctx)
        assert res.details["trivial_pr_count"] == 1
        assert 1 in res.details["trivial_pr_numbers"]
        assert res.details["generated_lines_excluded"] == 500


# ---------------------------------------------------------------------------
# parse_hunks — function-level hunk parsing (Phase 1c)
# ---------------------------------------------------------------------------

class TestParseHunks:
    def test_empty_patch(self):
        assert parse_hunks(None) == []
        assert parse_hunks("") == []

    def test_single_hunk_with_context(self):
        patch = (
            "@@ -10,5 +10,7 @@ def my_function():\n"
            " existing line\n"
            "+new line 1\n"
            "+new line 2\n"
            " another existing\n"
        )
        hunks = parse_hunks(patch)
        assert len(hunks) == 1
        assert hunks[0]["old_start"] == 10
        assert hunks[0]["old_count"] == 5
        assert hunks[0]["new_start"] == 10
        assert hunks[0]["new_count"] == 7
        assert hunks[0]["function_context"] == "def my_function():"
        assert hunks[0]["added_lines"] == 2
        assert hunks[0]["removed_lines"] == 0

    def test_multiple_hunks(self):
        patch = (
            "@@ -1,3 +1,4 @@ class Foo:\n"
            " line\n"
            "+added\n"
            "@@ -20,5 +21,3 @@ def bar():\n"
            " line\n"
            "-removed1\n"
            "-removed2\n"
        )
        hunks = parse_hunks(patch)
        assert len(hunks) == 2
        assert hunks[0]["function_context"] == "class Foo:"
        assert hunks[0]["added_lines"] == 1
        assert hunks[0]["removed_lines"] == 0
        assert hunks[1]["function_context"] == "def bar():"
        assert hunks[1]["added_lines"] == 0
        assert hunks[1]["removed_lines"] == 2

    def test_hunk_without_context(self):
        patch = (
            "@@ -0,0 +1,3 @@\n"
            "+line 1\n"
            "+line 2\n"
            "+line 3\n"
        )
        hunks = parse_hunks(patch)
        assert len(hunks) == 1
        assert hunks[0]["function_context"] is None
        assert hunks[0]["added_lines"] == 3

    def test_real_world_ts_context(self):
        """Test with realistic TypeScript-style hunk context."""
        patch = (
            "@@ -49,3 +49,4 @@ export {\n"
            " existing\n"
            "+  KebabMenuButton,\n"
        )
        hunks = parse_hunks(patch)
        assert len(hunks) == 1
        assert hunks[0]["function_context"] == "export {"

    def test_mixed_adds_and_removes(self):
        patch = (
            "@@ -5,4 +5,4 @@ def process():\n"
            " ctx\n"
            "-old_val = 1\n"
            "+new_val = 2\n"
            " more\n"
        )
        hunks = parse_hunks(patch)
        assert hunks[0]["added_lines"] == 1
        assert hunks[0]["removed_lines"] == 1


