class TestIsTestContent:
    def test_empty(self):
        assert not is_test_content(None)
        assert not is_test_content("")

    def test_python_pytest_import(self):
        patch = "@@ -0,0 +1,3 @@\n+import pytest\n+\n+def test_hello():\n+    assert True\n"
        assert is_test_content(patch)

    def test_python_unittest(self):
        patch = "@@ -0,0 +1,3 @@\n+from unittest import TestCase\n+class MyTest(TestCase):\n"
        assert is_test_content(patch)

    def test_python_test_function(self):
        patch = "@@ -0,0 +1,3 @@\n+def test_my_feature():\n+    result = compute()\n+    assert result == 42\n"
        assert is_test_content(patch)

    def test_js_describe_it(self):
        patch = "@@ -0,0 +1,5 @@\n+describe('MyComponent', () => {\n+  it('should render', () => {\n+    expect(true).toBe(true);\n+  });\n+});\n"
        assert is_test_content(patch)

    def test_js_jest_import(self):
        patch = "@@ -0,0 +1,2 @@\n+import { render, screen } from '@testing-library/react';\n"
        assert is_test_content(patch)

    def test_java_test_annotation(self):
        patch = "@@ -0,0 +1,4 @@\n+@Test\n+public void shouldWork() {\n+    assertEquals(1, 1);\n+}\n"
        assert is_test_content(patch)

    def test_rust_test_attribute(self):
        patch = "@@ -0,0 +1,4 @@\n+#[test]\n+fn test_add() {\n+    assert_eq!(2 + 2, 4);\n+}\n"
        assert is_test_content(patch)

    def test_go_test_function(self):
        patch = "@@ -0,0 +1,4 @@\n+func TestAdd(t *testing.T) {\n+    if add(2, 3) != 5 {\n+        t.Error(\"wrong\")\n+    }\n+}\n"
        assert is_test_content(patch)

    def test_normal_code_not_test(self):
        patch = "@@ -1,3 +1,5 @@\n def hello():\n-    print('hello')\n+    print('hello world')\n+    return True\n"
        assert not is_test_content(patch)

    def test_only_removed_test_code_not_detected(self):
        """Removed lines should not trigger test detection."""
        patch = "@@ -1,3 +1,1 @@\n-import pytest\n-def test_old():\n-    pass\n+# cleaned up\n"
        assert not is_test_content(patch)


class TestIsTestFileOrContent:
    def test_path_match(self):
        assert is_test_file_or_content("tests/test_foo.py")

    def test_content_match(self):
        patch = "@@ -0,0 +1,2 @@\n+import pytest\n+def test_bar():\n"
        assert is_test_file_or_content("src/helpers.py", patch)

    def test_neither(self):
        patch = "@@ -1,2 +1,2 @@\n-x = 1\n+x = 2\n"
        assert not is_test_file_or_content("src/main.py", patch)


# ---------------------------------------------------------------------------
# classify_diff_structure — structural diff classification (Phase 1e)
# ---------------------------------------------------------------------------

class TestClassifyDiffStructure:
    def test_empty(self):
        assert classify_diff_structure(None) == {}
        assert classify_diff_structure("") == {}

    def test_new_function(self):
        patch = (
            "@@ -0,0 +1,5 @@\n"
            "+def process_data(items):\n"
            "+    result = []\n"
            "+    for item in items:\n"
            "+        result.append(item * 2)\n"
            "+    return result\n"
        )
        result = classify_diff_structure(patch)
        assert result.get("new_function", 0) >= 1

    def test_new_class(self):
        patch = (
            "@@ -0,0 +1,3 @@\n"
            "+class UserService:\n"
            "+    def __init__(self):\n"
            "+        self.users = []\n"
        )
        result = classify_diff_structure(patch)
        assert result.get("new_class", 0) >= 1

    def test_conditional_change(self):
        patch = (
            "@@ -5,3 +5,5 @@\n"
            " x = get_value()\n"
            "+if x > threshold:\n"
            "+    handle_overflow(x)\n"
            " return x\n"
        )
        result = classify_diff_structure(patch)
        assert result.get("conditional_change", 0) >= 1

    def test_import_change(self):
        patch = (
            "@@ -1,2 +1,3 @@\n"
            " import os\n"
            "+import json\n"
            "+from pathlib import Path\n"
        )
        result = classify_diff_structure(patch)
        assert result.get("import_change", 0) >= 1

    def test_whitespace_only(self):
        patch = (
            "@@ -1,3 +1,3 @@\n"
            "-  x = 1\n"
            "+    x = 1\n"
        )
        # Only whitespace differs in the added content
        result = classify_diff_structure(patch)
        # Should detect as "other" or similar (not whitespace_only since content differs)
        assert isinstance(result, dict)

    def test_test_code_detection(self):
        patch = (
            "@@ -0,0 +1,3 @@\n"
            "+def test_my_feature():\n"
            "+    result = compute(42)\n"
            "+    assert result == 84\n"
        )
        result = classify_diff_structure(patch)
        assert result.get("test_code", 0) >= 1

    def test_error_handling(self):
        patch = (
            "@@ -10,3 +10,7 @@\n"
            " data = fetch()\n"
            "+try:\n"
            "+    parsed = json.loads(data)\n"
            "+except json.JSONDecodeError:\n"
            "+    parsed = {}\n"
        )
        result = classify_diff_structure(patch)
        assert result.get("error_handling", 0) >= 1

    def test_mixed_categories(self):
        patch = (
            "@@ -0,0 +1,6 @@\n"
            "+import logging\n"
            "+def new_handler():\n"
            "+    if condition:\n"
            "+        try:\n"
            "+            process()\n"
            "+        except Exception:\n"
        )
        result = classify_diff_structure(patch)
        # Should have multiple categories
        assert len(result) >= 2


