class TestExtractCodeBlocks:
    def test_no_code_blocks(self):
        assert extract_code_blocks("Just a plain comment.") == []

    def test_empty_input(self):
        assert extract_code_blocks("") == []
        assert extract_code_blocks(None) == []

    def test_single_fenced_block_with_language(self):
        text = "Check this:\n```python\ndef foo():\n    return 42\n```\nThoughts?"
        blocks = extract_code_blocks(text)
        assert len(blocks) == 1
        assert blocks[0][0] == "python"
        assert "def foo():" in blocks[0][1]

    def test_single_fenced_block_no_language(self):
        text = "Try:\n```\nx = 1\n```"
        blocks = extract_code_blocks(text)
        assert len(blocks) == 1
        assert blocks[0][0] is None
        assert "x = 1" in blocks[0][1]

    def test_multiple_blocks(self):
        text = "Before:\n```js\nconst a = 1;\n```\nAfter:\n```python\nx = 2\n```"
        blocks = extract_code_blocks(text)
        assert len(blocks) == 2
        assert blocks[0][0] == "js"
        assert blocks[1][0] == "python"

    def test_empty_code_block_skipped(self):
        text = "Empty:\n```python\n\n```\nEnd"
        blocks = extract_code_blocks(text)
        assert len(blocks) == 0  # empty content stripped away


class TestScoreCodeBlockQuality:
    def test_empty_code(self):
        assert score_code_block_quality("") == 0.0
        assert score_code_block_quality("   ") == 0.0

    def test_plain_text_in_code_block(self):
        # Plain text should get a low score
        score = score_code_block_quality("just some text here")
        assert score <= 0.6  # not a high code quality score

    def test_trivial_snippet(self):
        # Very short code — minimal credit
        score = score_code_block_quality("x = 1", "python")
        assert 0.2 <= score <= 0.8

    def test_substantive_python_code(self):
        code = (
            "def calculate_average(values: list[float]) -> float:\n"
            "    if not values:\n"
            "        return 0.0\n"
            "    return sum(values) / len(values)\n"
        )
        score = score_code_block_quality(code, "python")
        assert score >= 0.6  # real code should score well

    def test_substantive_javascript_code(self):
        code = (
            "function processItems(items) {\n"
            "    return items\n"
            "        .filter(item => item.active)\n"
            "        .map(item => ({ ...item, processed: true }));\n"
            "}\n"
        )
        score = score_code_block_quality(code, "javascript")
        assert score >= 0.6

    def test_language_alias_resolution(self):
        code = "x: int = sum(range(10))\nprint(x)\ny = x * 2"
        # "py" should resolve to "python" lexer
        score_py = score_code_block_quality(code, "py")
        score_python = score_code_block_quality(code, "python")
        assert score_py == score_python

    def test_unknown_language_falls_back_to_guess(self):
        code = "def hello():\n    print('hello')\n    return True\n"
        score = score_code_block_quality(code, "nonexistent_lang_xyz")
        assert score > 0.0  # should still produce a score via guess_lexer

    def test_real_code_beats_plain_text(self):
        real_code = (
            "async function fetchData(url: string): Promise<Response> {\n"
            "    const response = await fetch(url);\n"
            "    if (!response.ok) {\n"
            "        throw new Error(`HTTP ${response.status}`);\n"
            "    }\n"
            "    return response;\n"
            "}\n"
        )
        plain = "This is just a regular sentence with no code at all."
        assert score_code_block_quality(real_code, "typescript") > score_code_block_quality(plain)


class TestScoreCommentCodeQuality:
    def test_no_code(self):
        assert score_comment_code_quality("Just a plain comment.") == 0

    def test_inline_backticks_only(self):
        assert score_comment_code_quality("Use `foo()` instead of `bar()`.") == 10

    def test_fenced_code_block_scores_above_inline(self):
        body = "Try this:\n```python\ndef better():\n    return sorted(items)\n```"
        score = score_comment_code_quality(body)
        assert score >= 10  # at least as much as inline backticks
        assert score <= 25  # capped at 25

    def test_trivial_code_block_still_gets_minimum(self):
        body = "Use:\n```\nx\n```"
        score = score_comment_code_quality(body)
        assert score >= 10  # floor

    def test_substantive_code_gets_near_max(self):
        body = (
            "Consider this approach:\n"
            "```python\n"
            "def process_batch(items: list[dict]) -> list[Result]:\n"
            "    results = []\n"
            "    for item in items:\n"
            "        if item.get('active'):\n"
            "            result = transform(item)\n"
            "            results.append(result)\n"
            "    return results\n"
            "```\n"
        )
        score = score_comment_code_quality(body)
        assert score >= 20  # substantive code should score high

    def test_multiple_blocks_uses_best(self):
        body = (
            "Bad:\n```\nx\n```\n"
            "Good:\n```python\n"
            "def compute(a: int, b: int) -> int:\n"
            "    return a + b\n"
            "```"
        )
        score = score_comment_code_quality(body)
        # Should use the better block's score
        assert score >= 15


class TestScoreCommentIntegration:
    """Test that Pygments-enhanced scoring integrates correctly with _score_comment."""

    def test_code_block_comment_scores_higher_than_plain(self):
        from impact.metrics.plugins.influence.review_comment_substance import _score_comment
        plain = "This is a comment about the code quality and structure."
        with_code = (
            "Consider refactoring like this:\n"
            "```python\n"
            "def improved_handler(request):\n"
            "    validated = validate(request)\n"
            "    if not validated:\n"
            "        raise ValueError('Invalid')\n"
            "    return process(validated)\n"
            "```\n"
        )
        assert _score_comment(with_code) > _score_comment(plain)

    def test_score_comment_preserves_other_signals(self):
        from impact.metrics.plugins.influence.review_comment_substance import _score_comment
        # A comment with code + question + actionable language should score high
        body = (
            "Should we consider this approach instead?\n"
            "```python\n"
            "def better_way(data):\n"
            "    return sorted(data, key=lambda x: x.priority)\n"
            "```\n"
            "See https://docs.python.org/3/howto/sorting.html for reference."
        )
        score = _score_comment(body)
        # Length >= 100 (30) + code (10-25) + question (15) + link (10) + actionable (10)
        assert score >= 65


