        assert "superset-frontend" in modules
        assert "superset-frontend/packages/superset-ui-core" in modules
        assert "superset-frontend/plugins/chart-echarts" in modules
        assert "superset" in modules
        assert "tests" in modules
        # Should produce 5 distinct modules, not just 3 top-level dirs
        assert len(modules) == 5


