class TestParseFunctionsPython:
    def test_simple_function(self):
        code = "def hello():\n    print('hi')\n"
        funcs = parse_functions(code, "main.py")
        assert len(funcs) == 1
        assert funcs[0]["name"] == "hello"
        assert funcs[0]["kind"] == "function"
        assert funcs[0]["is_trivial"] is True  # single statement

    def test_complex_function(self):
        code = (
            "def process(items, threshold):\n"
            "    results = []\n"
            "    for item in items:\n"
            "        if item.value > threshold:\n"
            "            results.append(item)\n"
            "    return results\n"
        )
        funcs = parse_functions(code, "core.py")
        assert len(funcs) == 1
        f = funcs[0]
        assert f["name"] == "process"
        assert f["parameter_count"] == 2
        assert f["body_statement_count"] >= 2
        assert f["is_trivial"] is False

    def test_class_methods(self):
        code = (
            "class Service:\n"
            "    def __init__(self, config):\n"
            "        self.config = config\n"
            "    def get_name(self):\n"
            "        return self.config.name\n"
            "    def process(self, data):\n"
            "        validated = self.validate(data)\n"
            "        result = self.transform(validated)\n"
            "        return result\n"
        )
        funcs = parse_functions(code, "service.py")
        assert len(funcs) == 3
        kinds = {f["name"]: f["kind"] for f in funcs}
        assert kinds["__init__"] == "method"
        assert kinds["get_name"] == "method"
        assert kinds["process"] == "method"
        # __init__ and get_name are trivial (1 statement each)
        trivial_map = {f["name"]: f["is_trivial"] for f in funcs}
        assert trivial_map["__init__"] is True
        assert trivial_map["get_name"] is True
        assert trivial_map["process"] is False

    def test_empty_function(self):
        code = "def noop():\n    pass\n"
        funcs = parse_functions(code, "empty.py")
        assert len(funcs) == 1
        assert funcs[0]["is_trivial"] is True

    def test_line_numbers(self):
        code = (
            "# comment\n"
            "def first():\n"
            "    return 1\n"
            "\n"
            "def second():\n"
            "    return 2\n"
        )
        funcs = parse_functions(code, "lines.py")
        assert len(funcs) == 2
        assert funcs[0]["start_line"] == 2
        assert funcs[1]["start_line"] == 5


