# ---------------------------------------------------------------------------
# _parse_hunk_lines — counts only actual changed lines, not context
# ---------------------------------------------------------------------------


class TestParseHunkLines:
    def test_empty_patch(self):
        assert _parse_hunk_lines(None) == set()
        assert _parse_hunk_lines("") == set()

    def test_added_lines_only(self):
        patch = (
            "@@ -0,0 +1,3 @@\n"
            "+line 1\n"
            "+line 2\n"
            "+line 3\n"
        )
        result = _parse_hunk_lines(patch, "+")
        assert result == {1, 2, 3}

    def test_removed_lines_only(self):
        patch = (
            "@@ -5,3 +5,0 @@\n"
            "-old line 1\n"
            "-old line 2\n"
            "-old line 3\n"
        )
        result = _parse_hunk_lines(patch, "-")
        assert result == {5, 6, 7}

    def test_context_lines_excluded(self):
        """Context lines (starting with space) must NOT be counted as changed."""
        patch = (
            "@@ -10,5 +10,7 @@ def my_function():\n"
            " existing line\n"
            "+new line 1\n"
            "+new line 2\n"
            " another existing\n"
            " more existing\n"
        )
        # For the new side (+): only the two added lines
        added = _parse_hunk_lines(patch, "+")
        assert added == {11, 12}  # lines 10=context, 11=+, 12=+, 13=context, 14=context

        # For the old side (-): no removed lines in this patch
        removed = _parse_hunk_lines(patch, "-")
        assert removed == set()

    def test_mixed_adds_removes_context(self):
        """Correctly tracks line numbers through mixed additions, removals, and context."""
        patch = (
            "@@ -5,4 +5,4 @@ def process():\n"
            " ctx\n"
            "-old_val = 1\n"
            "+new_val = 2\n"
            " more\n"
        )
        added = _parse_hunk_lines(patch, "+")
        assert added == {6}  # line 5=context, skip -, line 6=+, line 7=context

        removed = _parse_hunk_lines(patch, "-")
        assert removed == {6}  # old line 5=context, old line 6=-

    def test_multiple_hunks(self):
        patch = (
            "@@ -1,2 +1,3 @@\n"
            " line1\n"
            "+added_first\n"
            " line2\n"
            "@@ -10,2 +11,3 @@\n"
            " line10\n"
            "+added_second\n"
            " line11\n"
        )
        added = _parse_hunk_lines(patch, "+")
        assert added == {2, 12}  # first hunk: ctx@1, add@2, ctx@3; second hunk: ctx@11, add@12, ctx@13

    def test_no_inflation_from_context(self):
        """Key regression test: old impl used hunk header counts which included context lines.
        A hunk @@ -10,5 +10,7 @@ with 2 added lines + 3 context lines used to return
        {10, 11, 12, 13, 14, 15, 16} (7 lines) instead of just the 2 actual additions."""
        patch = (
            "@@ -10,5 +10,7 @@ def foo():\n"
            " ctx1\n"
            " ctx2\n"
            "+add1\n"
            "+add2\n"
            " ctx3\n"
            " ctx4\n"
            " ctx5\n"
        )
        added = _parse_hunk_lines(patch, "+")
        # Should be exactly 2 lines, not 7
        assert len(added) == 2
        assert added == {12, 13}


