class TestIsDependencyFile:
    def test_exact_basenames_match(self):
        assert is_dependency_file("package.json")
        assert is_dependency_file("frontend/package.json")
        assert is_dependency_file("requirements.txt")
        assert is_dependency_file("deep/path/pyproject.toml")
        assert is_dependency_file("Cargo.toml")
        assert is_dependency_file("go.mod")
        assert is_dependency_file("pom.xml")

    def test_no_substring_false_positives(self):
        """Files containing dep filenames as substrings must NOT match."""
        assert not is_dependency_file("my_package.json_backup")
        assert not is_dependency_file("not_requirements.txt.bak")
        assert not is_dependency_file("src/cargo.toml.template")
        # But the basename itself still matches
        assert is_dependency_file("src/cargo.toml")

    def test_non_dep_files(self):
        assert not is_dependency_file("main.py")
        assert not is_dependency_file("src/components/Button.tsx")
        assert not is_dependency_file("")
        assert not is_dependency_file("README.md")

    def test_case_insensitive(self):
        assert is_dependency_file("PACKAGE.JSON")
        assert is_dependency_file("Gemfile")
        assert is_dependency_file("Pipfile.lock")


